def load() -> pd.DataFrame:
    import glob, os, re
    import pandas as pd
    files = sorted(glob.glob('data/environment/input/*_datasheet.csv'))
    rows = []
    for f in files:
        df = pd.read_csv(f, header=None, dtype=str, encoding='utf-8', engine='python')
        if df.shape[0] < 3:
            continue
        title = ''
        if not pd.isna(df.iloc[0,0]):
            title = str(df.iloc[0,0])
        site_row = df.iloc[1].fillna(method='ffill')
        key_row = df.iloc[2].fillna('')
        data = df.iloc[3:].reset_index(drop=True)
        cols = []
        for j in range(df.shape[1]):
            site = site_row[j] if not pd.isna(site_row[j]) else ''
            key = key_row[j] if not pd.isna(key_row[j]) else ''
            cols.append((str(site).strip(), str(key).strip()))
        data.columns = pd.MultiIndex.from_tuples(cols)
        # locate date column (first column whose key contains 'date')
        date_col = None
        for col in data.columns:
            if 'date' in col[1].lower():
                date_col = col
                break
        # iterate sites present in header
        sites = [s for s in sorted({c[0] for c in data.columns if str(c[0]).strip()}) if s]
        for i in range(data.shape[0]):
            raw_date = None
            if date_col is not None:
                raw_date = data.at[i, date_col]
            try:
                date = pd.to_datetime(raw_date, errors='coerce')
            except Exception:
                date = pd.NaT
            for site in sites:
                # find enterococcus column(s) for this site
                enter_cols = [c for c in data.columns if c[0]==site and 'enteroc' in c[1].lower()]
                tag_cols = [c for c in data.columns if c[0]==site and 'tag' in c[1].lower()]
                rain1_cols = [c for c in data.columns if c[0]==site and ('1-day' in c[1].lower() or ('1' in c[1] and 'day' in c[1] and 'rain' in c[1]) or ('1 day' in c[1].lower()))]
                # if no site-specific 1-day rain, try any column with key contains '1-day rain'
                if not rain1_cols:
                    rain1_cols = [c for c in data.columns if '1-day' in c[1].lower() or ('1' in c[1] and 'day' in c[1] and 'rain' in c[1])]
                enter_val = None
                tag_val = ''
                if enter_cols:
                    enter_val = data.at[i, enter_cols[0]]
                if tag_cols:
                    tag_val = data.at[i, tag_cols[0]]
                # build enterococcus_raw combining tag and enter value
                raw = None
                if (tag_val is not None and str(tag_val).strip() and str(tag_val).strip() != 'nan'):
                    tv = str(tag_val).strip()
                    ev = '' if enter_val is None else str(enter_val).strip()
                    if tv == '<' and ev:
                        raw = '<' + ev
                    else:
                        raw = tv + ev if tv and ev else (tv or ev)
                else:
                    raw = None if enter_val is None else str(enter_val).strip()
                # normalize raw (empty strings -> None)
                if raw is not None:
                    raw = raw.strip()
                    if raw == '' or raw.lower() == 'nan':
                        raw = None
                # numeric extraction
                num = None
                is_less = False
                if raw is not None:
                    if raw.startswith('<'):
                        is_less = True
                        m = re.search(r"(\d+\.?\d*)", raw)
                        if m:
                            try:
                                num = float(m.group(1))
                            except Exception:
                                num = None
                    else:
                        m = re.search(r"(\d+\.?\d*)", raw)
                        if m:
                            try:
                                num = float(m.group(1))
                            except Exception:
                                num = None
                # rain_1day
                rain1 = None
                if rain1_cols:
                    try:
                        rraw = data.at[i, rain1_cols[0]]
                        if rraw is not None and str(rraw).strip() and str(rraw).strip().lower()!='nan':
                            rain1 = float(str(rraw).strip())
                    except Exception:
                        rain1 = None
                beach = None
                if title:
                    # take text before ':' or first comma as beach name when possible
                    t = title
                    if ':' in t:
                        t = t.split(':',1)[0]
                    if ',' in t:
                        t = t.split(',',1)[0]
                    beach = t.strip()
                if not beach:
                    base = os.path.basename(f).replace('_datasheet.csv','').replace('.csv','')
                    beach = base.replace('_',' ').title()
                rows.append({
                    'date': date,
                    'beach_file': os.path.basename(f),
                    'beach': beach,
                    'site': site,
                    'enterococcus_raw': raw,
                    'enterococcus': num,
                    'enterococcus_is_less': bool(is_less),
                    'rain_1day': rain1,
                })
    return pd.DataFrame(rows)

def process(parsed_datasheets, boston_beaches_list):
    beaches = set(boston_beaches_list['beach'].str.strip())
    df = parsed_datasheets[parsed_datasheets['beach'].isin(beaches)]
    df = df[df['enterococcus'].notna()]
    failed = df[df['enterococcus'] > 104]
    failed_total = len(failed)
    if failed_total == 0:
        pct = 0.0
        failed_with_rain = 0
    else:
        failed_with_rain = int((failed['rain_1day'].fillna(0) > 0).sum())
        pct = failed_with_rain / failed_total * 100
    return pd.DataFrame({'pct': [round(pct, 2)], 'failed_total': [failed_total], 'failed_with_rain': [failed_with_rain]})
